import {leafCases,leafSource,leafCopy as T} from './leaf-accounts-content.mjs';
import {newLeafWork,changeLeafWork,countFor,leafAtomAccount,leafReferenceWork,leafAccountsView,lastLeafAccount,keepLeafAccount} from './leaf-accounts-core.mjs';
import {stopSpeech} from './play-media.mjs';
const clone=x=>structuredClone(x),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const own=(x,k)=>Object.hasOwn(x,k),ownerOK=x=>typeof x==='string'&&x.trim().length>0;
const bytes=x=>{try{return JSON.stringify(x);}catch{return null;}};
const button=(attrs,text,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(text)}</button>`;
const atomNames={C:'Carbon',H:'Hydrogen',O:'Oxygen'},elements=['C','H','O'],numberWords=['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve'];
const label=(s,id)=>s.energyOptions.find(o=>o.id===id)?.label||'Not chosen',species=(s,id)=>s.species.find(p=>p.id===id);
let visit=null;
export function resetLeafAccounts(){visit=null;}
function makeSlot(source,work){return {source:clone(source),work:clone(work||newLeafWork(source)),turn:'make',folds:{},status:''};}
function state(book,owner){if(!visit||visit.book!==book||visit.owner!==owner){visit={book,owner,screen:'draft',active:leafCases[0].id,card:null,drafts:new Map(),copies:new Map(),readonly:new Map(),page:null,boundRoot:null};visit.drafts.set(visit.active,makeSlot(leafSource(visit.active)));}return visit;}
const slot=v=>v.screen==='draft'?v.drafts.get(v.active):v.screen==='card'?v.readonly.get(v.card):null;
const formula=p=>elements.filter(e=>p.atoms[e]>0).map(e=>`${e}${p.atoms[e]>1?`<sub>${p.atoms[e]}</sub>`:''}`).join('');
const atomText=p=>elements.map(e=>`${atomNames[e]} ${p.atoms[e]}`).join('; ');
function molecules(p,count,key){return `<div class="la-molecules" aria-label="${esc(`${Math.min(count,3)} molecule groups shown; ${count} molecules total. ${atomText(p)} in each molecule.`)}">${Array.from({length:Math.min(count,3)},(_,i)=>`<div class="la-molecule" data-la-molecule="${esc(key)}" aria-label="Molecule ${i+1}">${elements.flatMap(e=>Array.from({length:p.atoms[e]},()=>`<span class="la-atom la-atom-${e}" data-la-atom="${e}">${e}</span>`)).join('')}</div>`).join('')}</div>`;}
function tile(s,w,l,readonly,editing){const p=species(s,l.speciesId),n=countFor(w,l.id);return `<article class="la-tile" data-la-slot="${esc(l.id)}" data-la-side="${l.side}"><h4>${esc(p.label)}</h4><p class="la-formula"><strong data-la-coefficient="${esc(l.id)}">${n}</strong><span aria-hidden="true"> × </span><span data-la-formula="${esc(p.id)}" aria-label="${esc(atomText(p))}">${formula(p)}</span></p>${editing?`<div class="la-unit-controls">${[-1,1].map(d=>button(`data-la-amount="${esc(l.id)}:${d}" aria-label="${d<0?'Minus 1':'Plus 1'}; ${esc(p.label)}, ${l.side==='in'?'used':'made'}"${readonly||n===(d<0?0:12)?' disabled':''}`,d<0?'Minus 1':'Plus 1')).join('')}</div>`:''}<p class="la-count-label">${n} ${n===1?'molecule':'molecules'} total</p>${molecules(p,n,l.id)}<p class="la-composition-label">Atoms in one molecule</p><dl class="la-composition" aria-label="Atoms in one molecule">${elements.map(e=>`<div><dt>${atomNames[e]}</dt><dd>${p.atoms[e]}</dd></div>`).join('')}</dl></article>`;}
function matter(s,w,readonly,editing){return `<section class="la-matter" aria-labelledby="la-matter-title"><h3 id="la-matter-title">Matter: count the atoms</h3><div class="la-matter-zones">${['in','out'].map((side,i)=>`${i?'<div class="la-direction" aria-label="Direction of this net summary">→</div>':''}<section class="la-zone la-zone-${side}"><h3>${side==='in'?'Used in this summary':'Made in this summary'}</h3>${s.slots.filter(l=>l.side===side).map(l=>tile(s,w,l,readonly,editing)).join('')}</section>`).join('')}</div></section>`;}
function energy(s,w,readonly,editing){return `<section class="la-energy"><h3>Energy: follow the transfer</h3><p class="la-energy-notice">Energy is not an atom tile. Light does not turn into the plant's matter.</p><div class="la-energy-pair">${[['fromId','Energy at the start'],['toId','Energy transferred to']].map(([field,title],i)=>`${i?'<span class="la-energy-arrow" aria-hidden="true">⇢</span>':''}<div>${editing?`<label>${title}<select data-la-energy="${field}"${readonly?' disabled':''}><option value=""${w.energy[field]===null?' selected':''}>Not chosen</option>${s.energyOptions.map(o=>`<option value="${esc(o.id)}"${w.energy[field]===o.id?' selected':''}>${esc(o.label)}</option>`).join('')}</select></label>${w.energy[field]!==null?`<p class="la-selected-caption" data-la-selected-caption="${field}">${esc(label(s,w.energy[field]))}</p>`:''}`:`<h4>${title}</h4><p data-la-chosen-energy="${field}">${esc(label(s,w.energy[field]))}</p>`}</div>`).join('')}</div><p>These are your chosen captions. Compare with the reference or talk them through with someone. They are not scored.</p></section>`;}
const signed=n=>n>0?`+${n}`:n<0?`−${-n}`:'0';
function totals(s,w){const a=leafAtomAccount(s,w);return `<section class="la-totals" data-la-totals><h3 id="la-count-title" tabindex="-1">The atom account</h3><p data-la-count-message>${esc(a.empty?'No molecules selected. Zero matches zero, but this is an empty summary.':a.matches?'The atom counts match. Matching atoms is a bookkeeping check. It does not show that this process happens.':'These atom counts do not match yet. The table shows how your selected amounts differ. This is your unfinished summary, not a claim that a plant creates or destroys atoms.')}</p><table><thead><tr><th scope="col">Atom</th><th scope="col">Used</th><th scope="col">Made</th><th scope="col">Made minus used</th></tr></thead><tbody>${elements.map(e=>`<tr><th scope="row">${atomNames[e]}</th><td data-la-total="used:${e}">${a.used[e]}</td><td data-la-total="made:${e}">${a.made[e]}</td><td data-la-total="difference:${e}">${signed(a.difference[e])}</td></tr>`).join('')}</tbody></table></section>`;}
function reference(s){const w=leafReferenceWork(s);return `<section class="la-reference" data-la-reference-shown><h3 id="la-reference-title" tabindex="-1">Reference summary, separate from yours</h3><p>This is a simplified net account of many steps. Your summary stays as you made it. Doubling every count keeps the same ratio; it does not show a faster or measured plant.</p><h4>${esc(s.process)}</h4><p>${esc(s.location)}</p><div class="la-reference-sides">${['in','out'].map(side=>`<section><h4>${side==='in'?'Used in this summary':'Made in this summary'}</h4><ul>${s.slots.filter(l=>l.side===side).map(l=>`<li>${countFor(w,l.id)} ${esc(species(s,l.speciesId).label)} <span class="la-reference-formula">(${formula(species(s,l.speciesId))})</span></li>`).join('')}</ul></section>`).join('')}</div><p>Energy at the start: ${esc(label(s,w.energy.fromId))}. Energy transferred to: ${esc(label(s,w.energy.toId))}.</p><p>${esc(s.energyReference.note)}</p></section>`;}
function fold(a,id,title,body){return `<details data-la-fold="${id}"${a.folds[id]?' open':''}><summary>${esc(title)}</summary>${body}</details>`;}
function teaching(a,readonly){const s=a.source,w=a.work,demo=species(s,s.teachingDemo.speciesId);return fold(a,'help','An explanation in parts',`${s.teaching.slice(0,w.exampleSeen).map((t,i)=>`<section data-la-teaching="${i}"><p>${esc(t)}</p>${i===0?`<p>${s.teachingDemo.count} ${esc(demo.label)} molecules</p>${molecules(demo,s.teachingDemo.count,'teaching')}`:''}</section>`).join('')}${!readonly?button(`data-la-example${w.exampleSeen===s.teaching.length?' disabled':''}`,w.exampleSeen?'Next explanation':'Show an explanation'):w.exampleSeen===0?'<p>No explanation frames were opened on this sheet. Work on a copy to explore them.</p>':''}`);}
function picture(){return `<svg class="la-plant-icon" viewBox="0 0 56 64" aria-hidden="true"><path d="M28 44V20M28 35C7 35 6 14 8 6c18 1 25 13 20 29ZM28 28C47 29 50 16 48 9c-15 0-21 8-20 19ZM28 44l-10 12m10-12 9 13m-9-13 1 17" fill="#edf5ef" stroke="#397958" stroke-width="3" stroke-linecap="round"/></svg>`;}
function activePage(a,readonly,copy){const s=a.source,w=a.work,editing=a.turn==='make';return `<div class="la-source-title">${picture()}<div><h2 id="la-title" tabindex="-1">${esc(s.title)}</h2><p class="la-process">${esc(s.process)}</p></div></div><p class="la-context">${esc(s.context)}</p>${readonly?`<p class="la-readonly">Kept summary. Its counts, captions and opened explanations stay unchanged.</p>${button('data-la-copy',copy?'Return to your copy':'Work on a copy',true)}`:''}<nav class="la-turns" aria-label="Two accounts">${button(`data-la-turn="make" aria-pressed="${editing}"`,'Make a summary',editing)}${button(`data-la-turn="read" aria-pressed="${!editing}"`,'Read both accounts',!editing)}</nav><h3 id="la-turn-title" tabindex="-1">${editing?'Make a summary':'Read both accounts'}</h3><p class="la-task" data-la-task>${esc(s.task)}</p>${matter(s,w,readonly,editing)}${energy(s,w,readonly,editing)}${!editing?`<div class="la-actions">${button(`data-la-count${readonly?' disabled':''}`,'Count atoms',true)}${!w.referenceShown?button(`data-la-reference${readonly?' disabled':''}`,'Show the reference summary'):''}</div>${w.countShown?totals(s,w):'<p>The atom totals have not been opened for this summary.</p>'}${w.referenceShown?reference(s):''}`:''}<div class="la-actions">${!readonly?button('data-la-keep','Keep this summary',true):''}<a href="#notes">Open Notes</a></div><p id="la-status" role="status" aria-live="polite" tabindex="-1">${esc(a.status)}</p>${fold(a,'diagram','Reading the molecule groups','<p>Each outlined group represents one molecule\'s composition, not its shape or bonds. The number outside the formula counts whole molecules. The small numbers inside the formula stay the same.</p>')}<p class="la-notice">${esc(s.notice)}</p>${fold(a,'about','About this model',`<p>${esc(s.location)}</p><p>${esc(s.about)}</p>`)}${teaching(a,readonly)}${readonly?`<p>${esc(s.returnQuestion)}</p>`:''}`;}
function shelf(v){const view=leafAccountsView(v.book),total=view.items.length;if(v.page===null){const last=view.items.findLast(x=>x.readable);v.page=Math.floor((last?.index??Math.max(0,total-1))/8);}v.page=Math.max(0,Math.min(v.page,Math.max(0,Math.ceil(total/8)-1)));const start=v.page*8;return `<h2 id="la-title" tabindex="-1">Kept summaries</h2>${view.status==='unavailable'?'<p>This saved format stays unchanged in Notes. You can still explore a draft.</p>':''}${total?`<p>Sheets ${start+1}–${Math.min(start+8,total)} of ${total}</p><ol class="la-shelf" start="${start+1}">${view.items.slice(start,start+8).map(r=>`<li>${r.readable?button(`data-la-card="${esc(r.id)}"`,`Sheet ${r.index+1} · ${r.raw.source.title}`):'<p>This earlier sheet is unavailable here. Its original stays unchanged in Notes.</p>'}</li>`).join('')}</ol><div class="la-actions">${button(`data-la-page="-1"${start===0?' disabled':''}`,'Earlier sheets')}${button(`data-la-page="1"${start+8>=total?' disabled':''}`,'Later sheets')}</div>`:view.status==='unavailable'?'':'<p>Keep a summary to find it here. Unfinished summaries are welcome.</p>'}<p id="la-status" role="status" tabindex="-1"></p>`;}
export function leafAccountsPage(book,owner){const v=state(book,owner);if(v.screen==='card'){const row=leafAccountsView(book).items.find(r=>r.readable&&r.id===v.card),old=v.readonly.get(v.card);if(row&&(!old||old.raw!==row.raw||old.rawBytes!==bytes(row.raw))){const a=makeSlot(row.raw.source,row.raw.work),rawBytes=bytes(row.raw);if(old?.rawBytes===rawBytes){a.turn=old.turn;a.folds={...old.folds};}Object.assign(a,{raw:row.raw,rawBytes});v.readonly.set(v.card,a);}else if(!row)v.readonly.delete(v.card);}if(v.screen==='draft'&&!slot(v)){if(!leafCases.some(c=>c.id===v.active))v.active=leafCases[0].id;v.drafts.set(v.active,makeSlot(leafSource(v.active)));}const a=slot(v);return `<section class="la-page" data-la-root><header><nav class="la-actions">${button('data-la-back','Back to Cell Studio')}${button('data-la-draft','Your summary')}${button('data-la-shelf','Kept summaries')}${button('data-la-hear data-speak=""','Hear this page')}</nav><h1 id="la-heading" tabindex="-1">A leaf's two accounts</h1></header>${v.screen==='shelf'?shelf(v):a?activePage(a,v.screen==='card',v.copies.has(v.card)):'<h2 id="la-title" tabindex="-1">This sheet is unavailable here</h2><p>Its original stays unchanged in Notes.</p><p id="la-status" role="status"></p>'}<details class="la-chooser" data-la-chooser${v.chooser?' open':''}><summary>Choose a selected cell and process</summary><div class="la-actions">${leafCases.map(c=>button(`data-la-case="${esc(c.id)}" aria-pressed="${v.screen==='draft'&&v.active===c.id}"`,c.title)).join('')}</div><p>Each draft waits while you stay in this visit.</p></details><footer><p>Keep work you want to return to. Leaving or reloading loses drafts that have not been kept.</p><p>Unfinished and unexpected summaries are welcome. Keeping one is not a score.</p></footer></section>`;}
export function leafAccountInvitation(book,{open=false}={}){const row=lastLeafAccount(book);if(!row)return '';const s=row.raw.source,w=row.raw.work;return `<section class="la-return"><h3>Return to Sheet ${row.index+1} · ${esc(s.title)}</h3><details data-la-return${open?' open':''}><summary>A kept matter and energy account</summary><p>${esc(s.process)}</p>${['in','out'].map(side=>`<p>${side==='in'?'Used':'Made'}: ${s.slots.filter(l=>l.side===side).map(l=>`${countFor(w,l.id)} ${esc(species(s,l.speciesId).label)}`).join('; ')}.</p>`).join('')}<p>Chosen energy captions: ${esc(label(s,w.energy.fromId))} → ${esc(label(s,w.energy.toId))}.</p><p>${esc(s.notice)}</p>${w.referenceShown?reference(s):''}<p>${esc(s.returnQuestion)}</p><a href="#living/bodies">Body clues → A leaf's two accounts → Kept sheets</a><p><a href="#living/plants">Compare with Seedlings after the storm</a></p></details></section>`;}
const speechNumber=n=>numberWords[n]??String(n);
function spokenConstruction(s,w){return s.slots.map(l=>{const n=countFor(w,l.id),p=species(s,l.speciesId);return `${l.side==='in'?'Used':'Made'}: ${speechNumber(n)} ${n===1?'molecule':'molecules'} of ${p.label}. In each molecule: ${elements.map(e=>`${p.atoms[e]} ${atomNames[e].toLowerCase()} atoms`).join(', ')}.`;});}
function spokenAccount(s,w){const a=leafAtomAccount(s,w);return [a.empty?T.empty:a.matches?T.match:T.different,...elements.map(e=>`${atomNames[e]}: ${a.used[e]} used, ${a.made[e]} made. ${a.difference[e]===0?'Same count.':`${speechNumber(Math.abs(a.difference[e]))} ${a.difference[e]>0?'more':'fewer'} ${atomNames[e].toLowerCase()} atoms on the made side.`}`)];}
export function bindLeafAccounts(book,ctx={}){
 ctx=ctx||{};const v=visit,root=document.querySelector('[data-la-root]');if(v){v.boundRoot=null;v.binding=null;}
 const required=['notebook','explorerId','isActive','isLeafActive','canExport'],callbacks=Object.fromEntries(required.map(k=>[k,ctx[k]]));
 const owner=()=>typeof ctx.explorerId==='function'?ctx.explorerId():null;
 if(!root||!v||v.book!==book||required.some(k=>typeof ctx[k]!=='function')||!ownerOK(owner())||v.owner!==owner())return;
 v.boundRoot=root;const binding={};v.binding=binding;const screen=v.screen,active=v.active,card=v.card,a=slot(v),source=a?.source,route=location.hash,rootChain=[],chains=new WeakMap();
 for(let n=root;n&&n!==document;n=n.parentNode)rootChain.push([n,n.parentNode]);
 let expected=a?.work,sourceBytes=bytes(source),workBytes=bytes(expected),rawRoot=book.leafAccounts,rawBytes=bytes(rawRoot),rootPresent=own(book,'leafAccounts');
 const chain=n=>{const out=[];for(let p=n;p&&p!==root;p=p.parentNode)out.push([p,p.parentNode]);return out;};
 const attached=n=>chains.has(n)&&root.isConnected&&n.isConnected&&root.contains(n)&&rootChain.every(([c,p])=>c.parentNode===p)&&chains.get(n).every(([c,p])=>c.parentNode===p);
 const visible=n=>{for(let p=n;p;p=p.parentElement){if(p.hidden||p.getAttribute?.('aria-hidden')==='true'||getComputedStyle(p).display==='none'||getComputedStyle(p).visibility==='hidden')return false;if(p.tagName==='DETAILS'&&!p.open&&p!==n&&!p.querySelector(':scope > summary')?.contains(n))return false;}return true;};
 const live=n=>{try{return visit===v&&v.book===book&&v.boundRoot===root&&v.binding===binding&&required.every(k=>ctx[k]===callbacks[k])&&ownerOK(owner())&&owner()===v.owner&&ctx.notebook()===book&&ctx.isActive()===true&&ctx.isLeafActive()===true&&route==='#living/bodies'&&location.hash===route&&document.querySelector('[data-la-root]')===root&&attached(n)&&visible(n)&&!n.disabled&&v.screen===screen&&v.active===active&&v.card===card&&slot(v)===a&&a?.source===source&&a?.work===expected&&bytes(source)===sourceBytes&&sourceBytes!==null&&bytes(expected)===workBytes&&workBytes!==null&&own(book,'leafAccounts')===rootPresent&&book.leafAccounts===rawRoot&&bytes(rawRoot)===rawBytes&&rawBytes!==null&&(screen!=='card'||leafAccountsView(book).items.some(r=>r.readable&&r.id===card&&r.raw===a.raw&&bytes(r.raw)===a.rawBytes));}catch{return false;}};
 const adopt=()=>{expected=a?.work;sourceBytes=bytes(source);workBytes=bytes(expected);rawRoot=book.leafAccounts;rawBytes=bytes(rawRoot);rootPresent=own(book,'leafAccounts');};
 const guard=n=>{chains.set(n,chain(n));for(const type of ['click','input','change','toggle','keydown','focusin'])n.addEventListener(type,e=>{if(!live(n)){e.preventDefault();e.stopImmediatePropagation();}},{capture:true});};
 guard(root);root.querySelectorAll('button,a,select,details,summary,[data-speak]').forEach(guard);
 const stop=()=>{stopSpeech();ctx.stopSpeech?.();ctx.stopSound?.();};
 const folds=()=>{if(a)root.querySelectorAll('[data-la-fold]').forEach(n=>{if(attached(n))a.folds[n.dataset.laFold]=n.open;});const chooser=root.querySelector('[data-la-chooser]');if(chooser&&attached(chooser))v.chooser=chooser.open;};
 const redraw=(selector='#la-title')=>{ctx.render?.();const r=document.querySelector('[data-la-root]'),candidate=r?.querySelector(selector),n=candidate&&!candidate.disabled&&visible(candidate)?candidate:r?.querySelector('#la-title,#la-heading');n?.focus({preventScroll:true});if(n){const b=n.getBoundingClientRect();if(b.top<0||b.bottom>innerHeight)n.scrollIntoView({block:'nearest'});}};
 const message=text=>{if(a)a.status=text;const n=root.querySelector('#la-status');if(n)n.textContent=text;};
 const attr=(name,value)=>`[data-la-${name}="${CSS.escape(String(value))}"]`;
 function update(action,value){if(screen!=='draft'||!a)return false;const next=changeLeafWork(source,a.work,action,value);if(!next)return false;a.work=next;adopt();return true;}
 function on(selector,fn,target='#la-title'){root.querySelectorAll(selector).forEach(n=>n.addEventListener('click',()=>{if(!live(n))return;folds();message('');stop();if(fn(n)!==false)redraw(typeof target==='function'?target(n):target);}));}
 const back=root.querySelector('[data-la-back]');if(back)back.textContent=ctx.backLabel||'Back to Cell Studio';
 on('[data-la-back]',()=>{ctx.onBack?.();return false;});
 on('[data-la-shelf]',()=>{v.screen='shelf';});
 on('[data-la-draft]',()=>{if(!v.drafts.has(v.active)){v.active=leafCases.some(c=>c.id===v.active)?v.active:leafCases[0].id;v.drafts.set(v.active,makeSlot(leafSource(v.active)));}v.screen='draft';v.card=null;});
 on('[data-la-case]',n=>{const id=n.dataset.laCase;if(!leafCases.some(c=>c.id===id))return false;if(!v.drafts.has(id))v.drafts.set(id,makeSlot(leafSource(id)));v.active=id;v.screen='draft';v.card=null;});
 on('[data-la-card]',n=>{if(!leafAccountsView(book).items.some(r=>r.readable&&r.id===n.dataset.laCard))return false;v.card=n.dataset.laCard;v.screen='card';});
 on('[data-la-page]',n=>{v.page+=Number(n.dataset.laPage);},n=>attr('page',-Number(n.dataset.laPage)));
 on('[data-la-turn]',n=>{if(!a||!['make','read'].includes(n.dataset.laTurn))return false;a.turn=n.dataset.laTurn;},'#la-turn-title');
 on('[data-la-amount]',n=>{const raw=n.dataset.laAmount,i=raw.lastIndexOf(':'),id=raw.slice(0,i),delta=Number(raw.slice(i+1));if(![-1,1].includes(delta))return false;const result=update('amount',{slotId:id,count:countFor(a.work,id)+delta});if(result){const count=countFor(a.work,id);if(count===0||count===12)a.status=`${count} ${count===1?'molecule':'molecules'} of ${species(source,source.slots.find(l=>l.id===id).speciesId).label}. This is the limit of this count control.`;}return result;},n=>{const raw=n.dataset.laAmount,i=raw.lastIndexOf(':'),id=raw.slice(0,i),delta=Number(raw.slice(i+1)),count=countFor(a.work,id);return attr('amount',`${id}:${count===0||count===12?-delta:delta}`);});
 root.querySelectorAll('[data-la-energy]').forEach(n=>n.addEventListener('change',()=>{if(!live(n))return;folds();message('');stop();if(update('energy',{field:n.dataset.laEnergy,id:n.value||null}))redraw(attr('energy',n.dataset.laEnergy));}));
 on('[data-la-count]',()=>update('count'),'#la-count-title');
 on('[data-la-reference]',()=>update('reference'),'#la-reference-title');
 on('[data-la-example]',()=>{if(!update('example'))return false;a.folds.help=true;},()=>a.work.exampleSeen===source.teaching.length?'[data-la-fold="help"] > summary':'[data-la-example]');
 on('[data-la-copy]',()=>{if(screen!=='card'||!a?.raw)return false;let key=v.copies.get(card);if(!key||!v.drafts.has(key)){key=`copy:${card}`;const copy=makeSlot(a.raw.source,a.raw.work);copy.turn=a.turn;copy.folds={...a.folds};v.drafts.set(key,copy);v.copies.set(card,key);}v.active=key;v.screen='draft';v.card=null;});
 on('[data-la-keep]',()=>{if(screen!=='draft'||!a)return false;const id=keepLeafAccount(book,source,a.work,{canExport:ctx.canExport});if(!id){message('This summary could not be kept safely. Your draft and earlier notes stay unchanged. Download Notes or keep exploring.');root.querySelector('#la-status')?.focus({preventScroll:true});return false;}adopt();let saved;try{saved=ctx.save?.();}catch{saved={ok:false};}const row=leafAccountsView(book).items.find(r=>r.readable&&r.id===id);if(!row)return false;const kept=makeSlot(row.raw.source,row.raw.work);Object.assign(kept,{turn:a.turn,folds:{...a.folds},raw:row.raw,rawBytes:bytes(row.raw),status:saved?.enabled===false?'This summary is kept in this open page. Saving is off; download Notes before closing.':saved?.ok===false?'This summary is kept in this open page. Device storage did not save; download Notes before closing.':'This summary is kept. If saving is off, download Notes before leaving.'});v.readonly.set(id,kept);v.drafts.delete(active);v.card=id;v.screen='card';v.page=Math.floor(row.index/8);},'#la-status');
 root.querySelectorAll('[data-la-fold]').forEach(n=>n.addEventListener('toggle',()=>{if(!live(n)||!a)return;stop();a.folds[n.dataset.laFold]=n.open;}));
 const chooser=root.querySelector('[data-la-chooser]');chooser?.addEventListener('toggle',()=>{if(live(chooser)){stop();v.chooser=chooser.open;}});
 const hear=root.querySelector('[data-la-hear]');hear?.addEventListener('click',()=>{if(!live(hear))return;folds();message('');stop();const words=[T.label];if(screen==='shelf'){words.push('Kept summaries.',...leafAccountsView(book).items.slice(v.page*8,v.page*8+8).map(r=>r.readable?`Sheet ${r.index+1}. ${r.raw.source.title}`:'This earlier sheet is unavailable here.'));}else if(a){words.push(source.title,source.context,source.process,a.turn==='make'?T.makeTurn:T.readTurn,source.task,...spokenConstruction(source,a.work),T.energyNotice,`Energy at the start: ${label(source,a.work.energy.fromId)}. Energy transferred to: ${label(source,a.work.energy.toId)}.`,T.captionNote,source.notice);if(a.turn==='read'){if(a.work.countShown)words.push(...spokenAccount(source,a.work));if(a.work.referenceShown){const ref=leafReferenceWork(source);words.push(T.referenceHeading,T.referenceIntro,source.process,source.location,...spokenConstruction(source,ref),`Energy at the start: ${label(source,ref.energy.fromId)}. Energy transferred to: ${label(source,ref.energy.toId)}.`,source.energyReference.note);}}if(a.folds.diagram)words.push(T.diagramNote);if(a.folds.about)words.push(source.location,source.about);if(a.folds.help){words.push(...source.teaching.slice(0,a.work.exampleSeen));if(a.work.exampleSeen>0){const p=species(source,source.teachingDemo.speciesId);words.push(`${speechNumber(source.teachingDemo.count)} molecules of ${p.label}. In each molecule: ${atomText(p)}.`);}}if(screen==='card')words.push(source.returnQuestion);}hear.dataset.speak=words.join('\n\n');adopt();},{capture:true});
 root.querySelectorAll('a,summary').forEach(n=>n.addEventListener('click',()=>{if(live(n))stop();}));
}
